<script setup>
import { 
  MenubarRoot,
  MenubarMenu,
  MenubarTrigger,
  MenubarPortal,
  MenubarContent,
} from 'reka-ui'
import MenubarItem from '../main-menu/MenubarItem.vue'
import MenuDivider from '../main-menu/MenuDivider.vue'
</script>

<template>
  <MenubarRoot>
    <MenubarMenu>
      <MenubarTrigger class="MenubarTrigger click">
        <div class="flex items-center gap-2 mx-1">
          <!-- Loading spinner when app is loading or image is loading -->
          <span v-if="loading || (currentImageUrl && !imageOk && !imageError)" class="loading loading-bars loading-xs shrink-0 text-info"></span>
          <!-- Image icon if loaded successfully -->
          <img
            v-else-if="currentImageUrl && imageOk"
            :src="currentImageUrl"
            alt="App icon"
            class="w-4 h-4 object-contain"
            @load="onImageLoad"
            @error="onImageError"
          />
          <!-- Font Awesome icon -->
          <i
            v-else-if="awesomeIcon"
            :class="awesomeIcon"
          ></i>
          <!-- Default icons -->
          <i v-else-if="isFileViewer" class="fa-solid fa-file-lines"></i>
          <i v-else class="fa-solid fa-bars"></i>
        </div>
      </MenubarTrigger>
      <MenubarPortal>
        <MenubarContent
          class="text-xs outline-none bg-base-100 rounded-lg p-[5px] border border-white/30 shadow-sm [animation-duration:_400ms] [animation-timing-function:_cubic-bezier(0.16,_1,_0.3,_1)] will-change-[transform,opacity]"
        >
          <MenubarItem @click.stop="$ui.cloneApp(app)">
            Duplicate
          </MenubarItem>
          <MenubarItem @click.stop="$ui.openNewWindowAppPanel(app)" v-if="app.path">
            New window <i class="fa-solid fa-arrow-up-right-from-square"></i>
          </MenubarItem>
          <MenuDivider />
          <MenubarItem @click.stop="closeApp" class="text-error">
            <i class="fa-solid fa-xmark"></i> Close
          </MenubarItem>
        </MenubarContent>
      </MenubarPortal>
    </MenubarMenu>
  </MenubarRoot>
</template>

<script>
export default {
  props: ['app', 'iconClass', 'loading'],
  data() {
    return {
      imageOk: false,
      imageError: false,
      currentImageUrl: null,
      triedFallback: false,
    }
  },
  computed: {
    liveApp() {
      return this.$ui.openApps[this.app?.tabId] || this.app
    },
    currentProjectId() {
      return this.liveApp?.params?.project_id
    },
    isFileViewer() {
      return !!this.app?.params?.filePath
    },
    isImageIcon() {
      if (!this.app?.icon) return false
      return this.app.icon.startsWith('http') || this.app.icon.startsWith('data:image')
    },
    awesomeIcon() {
      if (this.app?.icon?.includes("fa"))
        return this.app.icon + " fa-sm"
      return null
    },
    primaryImageUrl() {
      if (this.app.icon?.startsWith('http')) return this.app.icon
      if (this.app.icon?.startsWith('data:image')) return this.app.icon
      return null
    },
    fallbackImageUrl() {
      const path = this.app.path?.split("#")[0]
      if (path) {
        const sep = this.app.path?.endsWith("/") ? "" : "/"
        return `${path}${sep}favicon.ico`
      }
      return null
    }
  },
  watch: {
    app() {
      this.resetImageState()
      this.setImageUrl()
    }
  },
  mounted() {
    this.setImageUrl()
  },
  methods: {
    closeApp() {
      this.$ui.closeApp(this.app)
    },
    resetImageState() {
      this.imageOk = false
      this.imageError = false
      this.triedFallback = false
      this.currentImageUrl = null
    },
    setImageUrl() {
      if (this.isImageIcon) {
        this.currentImageUrl = this.primaryImageUrl
      } else if (this.fallbackImageUrl) {
        // Try favicon even if icon is not an image URL
        this.currentImageUrl = this.fallbackImageUrl
      }
    },
    onImageLoad() {
      this.imageOk = true
    },
    onImageError() {
      // Try favicon fallback if available and not already tried
      if (!this.triedFallback && this.fallbackImageUrl && this.currentImageUrl !== this.fallbackImageUrl) {
        this.triedFallback = true
        this.currentImageUrl = this.fallbackImageUrl
      } else {
        this.imageError = true
      }
    }
  }
}
</script>
